107	    // Remove the window associated with the form.
108	    // This is done by explicitly creating and owning the window
109	    // as opposed to having it being done by the form
110	    ng::Vector2i previousPosition(15, parentWindow->height());
111	    if (_window)
112	    {
113	        for (int i = 0; i < _window->child_count(); i++)
114	        {
115	            _window->remove_child_at(i);
116	        }
117	        // We don't want the property editor to move when
118	        // we update it's contents so cache any previous position
119	        // to use when we create a new window.
120	        previousPosition = _window->position();
121	        parent.remove_child(_window);
122	    }
123	
124	    if (previousPosition.x() < 0)
125	        previousPosition.x() = 0;
126	    if (previousPosition.y() < 0)
127	        previousPosition.y() = 0;
128	
129	    _window = new ng::Window(&parent, "Property Editor");
130	    _window->set_layout(new ng::GroupLayout());
131	    _window->set_position(previousPosition);
132	    _window->set_visible(_visible);
133	
134	    ng::ref<ng::VScrollPanel> scroll_panel = new ng::VScrollPanel(_window);
135	    scroll_panel->set_fixed_height(300);
136	    _container = new ng::Widget(scroll_panel);
137	    _container->set_layout(new ng::GroupLayout(1, 1, 1, 1));
