147	void GlslRenderer::render()
148	{
149	    if (!_context || !_context->makeCurrent())
150	    {
151	        throw ExceptionRenderError("Invalid OpenGL context in render");
152	    }
153	
154	    // Set up target
155	    _framebuffer->bind();
156	
157	    glClearColor(_screenColor[0], _screenColor[1], _screenColor[2], 1.0f);
158	
159	    glEnable(GL_DEPTH_TEST);
160	    glEnable(GL_FRAMEBUFFER_SRGB);
161	    glDepthFunc(GL_LESS);
162	    glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
163	
164	    try
165	    {
166	        // Bind program and input parameters
167	        if (_program)
168	        {
169	            // Check if we have any attributes to bind. If not then
170	            // there is nothing to draw
171	            if (!_program->hasActiveAttributes())
172	            {
173	                throw ExceptionRenderError("Program has no input vertex data");
174	            }
175	            else
176	            {
177	                // Bind the shader program.
178	                if (!_program->bind())
179	                {
180	                    throw ExceptionRenderError("Cannot bind inputs without a valid program");
181	                }
182	
183	                // Update uniforms and attributes.
184	                _program->getUniformsList();
185	                _program->getAttributesList();
186	
187	                // Bind shader properties.
188	                _program->bindViewInformation(_camera);
189	                _program->bindTextures(_imageHandler);
190	                _program->bindLighting(_lightHandler, _imageHandler);
191	                _program->bindTimeAndFrame();
192	
193	                // Set blend state for the given material.
194	                bool isTransparent = _program->getShader()->hasAttribute(HW::ATTR_TRANSPARENT);
195	                if (isTransparent)
196	                {
197	                    glEnable(GL_BLEND);
198	                    glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
199	                }
200	                else
201	                {
202	                    glDisable(GL_BLEND);
203	                }
204	
205	                // Bind each mesh and draw its partitions.
206	                for (MeshPtr mesh : _geometryHandler->getMeshes())
207	                {
208	                    _program->bindMesh(mesh);
209	                    for (size_t i = 0; i < mesh->getPartitionCount(); i++)
210	                    {
211	                        MeshPartitionPtr part = mesh->getPartition(i);
212	                        _program->bindPartition(part);
213	                        MeshIndexBuffer& indexData = part->getIndices();
214	
215	                        if (isTransparent)
216	                        {
217	                            glEnable(GL_CULL_FACE);
218	                            glCullFace(GL_FRONT);
219	                            glDrawElements(GL_TRIANGLES, (GLsizei) indexData.size(), GL_UNSIGNED_INT, (void*) 0);
220	                            glCullFace(GL_BACK);
221	                            glDisable(GL_CULL_FACE);
222	                        }
223	                        glDrawElements(GL_TRIANGLES, (GLsizei) indexData.size(), GL_UNSIGNED_INT, (void*) 0);
224	                    }
225	                }
226	
227	                // Unbind resources
228	                _imageHandler->unbindImages();
229	                _program->unbind();
230	
231	                // Restore blend state.
232	                if (_program->getShader()->hasAttribute(HW::ATTR_TRANSPARENT))
233	                {
234	                    glDisable(GL_BLEND);
235	                }
236	            }
237	        }
238	    }
239	    catch (ExceptionRenderError& e)
240	    {
241	        _framebuffer->unbind();
242	        throw e;
243	    }
244	
245	    // Unset target
246	    _framebuffer->unbind();
247	}
